#!/usr/bin/env bash
# End-to-end test: build bundles on this (online) host, then install and use
# them in a fresh, air-gapped Ubuntu VM (see vm.sh).
#
#   plain.tar  the template flake as-is (no Lix, no direnv)
#   full.tar   tests/consumer via bundleDevShells with includeLix, includeDirenv
#              and an SBOM generated by `nix run .#sbom` (sbomnix, as in the guide)
#   home.tar   tests/consumer-home: a real Home Manager configuration via
#              bundleHomeConfigurations, with includeLix and an SBOM; installed
#              on a second, freshly reset VM
#
# Usage: tests/e2e.sh   (VM images live in $AIRGAP_VM_WORK, default ~/.cache/nix-airgap-e2e)
set -o errexit -o nounset -o pipefail

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
export AIRGAP_VM_WORK="${AIRGAP_VM_WORK:-${XDG_CACHE_HOME:-$HOME/.cache}/nix-airgap-e2e}"
VM="${REPO}/tests/vm.sh"
OUT="${AIRGAP_VM_WORK}/bundles"
# Build against the same nixpkgs this repo is locked to.
NIXPKGS="github:NixOS/nixpkgs/$(jq -r .nodes.nixpkgs.locked.rev "${REPO}/flake.lock")"
OVERRIDES=(--no-write-lock-file --override-input airgap "path:${REPO}" --override-input nixpkgs "$NIXPKGS")
mkdir -p "$OUT"

step() { printf '\n### %s\n' "$*"; }

step "Generating the consumer's SBOM"
# sbomnix evaluates the flake itself (no --override-input), so use a copy whose
# airgap input points straight at this repo.
consumer="$(mktemp -d)"
home_consumer="$(mktemp -d)"
trap 'rm -rf "$consumer" "$home_consumer" "${template:-}"' EXIT
sed "s|github:Marauder586/nix-airgap|path:${REPO}|" "${REPO}/tests/consumer/flake.nix" >"${consumer}/flake.nix"
nix run "path:${REPO}#sbom" -- "${consumer}#airgap-default" "${consumer}/sbom.cdx.json"
# It must cover the shell (sbomnix names components like "go-1.26.8"), direnv,
# and the Lix installer, tarball and the store paths inside the tarball.
jq -e '
  any(.components[].name; test("^go-[0-9]"))
  and any(.components[]; ."bom-ref" | test("-direnv-[0-9.]+\\.drv$"))
  and any(.components[]; ."bom-ref" == "lix-installer")
  and any(.components[]; ."bom-ref" == "lix-tarball")
  and any(.components[]; (.properties // []) | any(.value == "lix-tarball"))
' "${consumer}/sbom.cdx.json" >/dev/null
echo "SBOM has $(jq '.components | length' "${consumer}/sbom.cdx.json") components: go, direnv and Lix included"

step "Generating the Home Manager consumer's SBOM"
sed "s|github:Marauder586/nix-airgap|path:${REPO}|" "${REPO}/tests/consumer-home/flake.nix" >"${home_consumer}/flake.nix"
nix run "path:${REPO}#sbom" -- "${home_consumer}#airgap-home-ubuntu" "${home_consumer}/sbom.cdx.json"
jq -e '
  (.metadata.component."bom-ref" | test("-home-manager-generation\\.drv$"))
  and any(.components[].name; test("^hello"))
  and any(.components[]; ."bom-ref" == "lix-installer")
' "${home_consumer}/sbom.cdx.json" >/dev/null
echo "Home SBOM has $(jq '.components | length' "${home_consumer}/sbom.cdx.json") components, rooted at the activation package, Lix included"

step "Building bundles"
template="$(mktemp -d)"
cp "${REPO}/templates/devshell/flake.nix" "$template/"
nix build "path:${template}#airgap" "${OVERRIDES[@]}" -o "${OUT}/plain.tar"
nix build "path:${consumer}#airgap-default" "${OVERRIDES[@]}" -o "${OUT}/full.tar"
nix build "path:${home_consumer}#airgap-home-ubuntu" "${OVERRIDES[@]}" -o "${OUT}/home.tar"
ls -lhL "${OUT}"/*.tar

step "Booting a fresh air-gapped VM"
"$VM" reset
"$VM" start
"$VM" scp "${OUT}/plain.tar" "${OUT}/full.tar"

step "Testing in the VM"
"$VM" ssh 'bash -s' <<'VMTEST'
set -o errexit -o nounset -o pipefail
pass() { echo "PASS: $*"; }
fail() { echo "FAIL: $*"; exit 1; }
go_ok() { grep -q '^go version go1\.' <<<"$1" || fail "expected go version, got: $1"; }

curl -sS -m 5 https://cache.nixos.org >/dev/null 2>&1 && fail "VM can reach the internet"
pass "VM is air-gapped"
[ ! -e /nix ] || fail "/nix already exists"

out=$(sh plain.tar ~/p1 2>&1) && fail "plain bundle succeeded without Nix: $out"
grep -q 'Nix is not installed' <<<"$out" || fail "unexpected error: $out"
pass "plain bundle refuses to run without Nix, with a clear error"

mkdir x && tar -xf full.tar -C x
files=$(cd x && find . -type f | sort | tr '\n' ' ')
[ "$files" = "./cache.tar.zst ./lix/lix-2.95.2-x86_64-linux.tar.xz ./lix/lix-installer ./manifest ./sbom.cdx.json ./stub.sh " ] ||
  fail "unexpected tar contents: $files"
rm -rf x
pass "bundle extracts as a plain tar with no stray files"

sh full.tar --sbom ~/sbom
python3 - ~/sbom/sbom.cdx.json <<'PY' || fail "extracted SBOM doesn't cover the shell, direnv and Lix"
import json, sys
d = json.load(open(sys.argv[1]))
refs = [c["bom-ref"] for c in d["components"]]
assert d["bomFormat"] == "CycloneDX"
assert any(c["name"].startswith("go-") for c in d["components"]), "go"
assert any("-direnv-" in r for r in refs), "direnv"
assert "lix-installer" in refs and "lix-tarball" in refs, "lix"
PY
[ ! -e /nix ] || fail "--sbom touched /nix"
out=$(sh plain.tar --sbom ~/sbom2 2>&1) && fail "--sbom succeeded on a bundle without an SBOM"
grep -q 'has no SBOM' <<<"$out" || fail "unexpected error: $out"
pass "--sbom extracts an SBOM covering the shell, direnv and Lix before Nix is installed (and errors without one)"

sh full.tar --dry-run ~/p2 >/dev/null 2>&1
[ ! -e /nix ] && [ ! -e ~/p2 ] || fail "--dry-run changed something"
pass "--dry-run makes no changes"

time sh full.tar ~/p2
. /nix/var/nix/profiles/default/etc/profile.d/nix-daemon.sh
command -v direnv >/dev/null || fail "direnv was not installed"
direnv allow ~/p2
go_ok "$(direnv exec ~/p2 go version)"
pass "full bundle on a blank machine: installs Lix + direnv, and direnv loads go"

chmod +x plain.tar
./plain.tar ~/p1
go_ok "$(cd ~/p1 && bash -c 'source .envrc && go version')"
pass "plain bundle, run directly as ./plain.tar, works with the existing Nix"

sh plain.tar ~/p1 >/dev/null 2>&1 || fail "re-running the bundle failed"
[ ! -e ~/p1/.envrc.airgap ] || fail "re-run treated its own .envrc as foreign"
pass "re-running is idempotent"

mkdir -p ~/p3 && echo 'export FOO=1' >~/p3/.envrc
sh plain.tar ~/p3 >/dev/null 2>&1
[ "$(cat ~/p3/.envrc)" = 'export FOO=1' ] || fail "existing .envrc was overwritten"
go_ok "$(cd ~/p3 && bash -c 'source .envrc.airgap && go version')"
pass "an existing .envrc is preserved; .envrc.airgap is written instead"

before=$(du -sm /nix/store | cut -f1)
sudo /nix/var/nix/profiles/default/bin/nix-collect-garbage -d >/dev/null 2>&1
after=$(du -sm /nix/store | cut -f1)
echo "store: ${before} MiB before GC, ${after} MiB after"
rm -f ~/p1/.direnv/airgap-*-env.sh
go_ok "$(cd ~/p1 && bash -c 'source .envrc && go version')"
go_ok "$(direnv exec ~/p2 go version)"
pass "shells survive nix-collect-garbage and rebuild their cache offline"

VMTEST

step "Booting a second fresh VM for the Home Manager bundle"
"$VM" ssh 'sudo poweroff' 2>/dev/null || true
sleep 3
"$VM" reset
"$VM" start
"$VM" scp "${OUT}/home.tar"

step "Testing the Home Manager bundle in the VM"
"$VM" ssh 'bash -s' <<'VMTEST'
set -o errexit -o nounset -o pipefail
pass() { echo "PASS: $*"; }
fail() { echo "FAIL: $*"; exit 1; }

curl -sS -m 5 https://cache.nixos.org >/dev/null 2>&1 && fail "VM can reach the internet"
[ ! -e /nix ] || fail "/nix already exists"
cp home.tar /tmp/home.tar && chmod 644 /tmp/home.tar
sudo useradd -m bob
out=$(sudo -u bob -H sh /tmp/home.tar 2>&1) && fail "home bundle activated for the wrong user: $out"
grep -q "is for user 'ubuntu'" <<<"$out" || fail "unexpected error: $out"

[ ! -e /nix ] || fail "the wrong-user check ran after installing something"
pass "home bundle refuses a different user before installing anything"

sh home.tar --sbom ~/hsbom
python3 - ~/hsbom/sbom.cdx.json <<'PY' || fail "home SBOM doesn't describe the configuration and Lix"
import json, sys
d = json.load(open(sys.argv[1]))
refs = [c["bom-ref"] for c in d["components"]]
assert d["metadata"]["component"]["bom-ref"].endswith("-home-manager-generation.drv")
assert any(c["name"].startswith("hello") for c in d["components"])
assert "lix-installer" in refs and "lix-tarball" in refs
PY

cp ~/.bashrc ~/bashrc.stock
mkdir -p ~/.config/airgap-test
echo user-original >~/.config/airgap-test/settings.conf
time sh home.tar
[ -x /nix/var/nix/profiles/default/bin/nix ] || fail "Lix wasn't installed from the home bundle"
[ "$(cat ~/.airgap-test)" = from-home-manager ] || fail "managed file missing"
cmp -s ~/.bashrc.airgap.bak ~/bashrc.stock || fail "stock ~/.bashrc wasn't moved to ~/.bashrc.airgap.bak"
[ -L ~/.bashrc ] || fail "~/.bashrc isn't managed by Home Manager"
[ "$(cat ~/.config/airgap-test/settings.conf)" = managed-by-home-manager ] ||
  fail "~/.config/airgap-test/settings.conf wasn't replaced by the managed one"
[ "$(cat ~/.config/airgap-test/settings.conf.airgap.bak)" = user-original ] ||
  fail "the existing ~/.config file wasn't moved to settings.conf.airgap.bak"
out=$(bash -lic 'airgap-test; hello --version | head -1; jq --version' 2>/dev/null)
grep -q hm-alias-works <<<"$out" && grep -q 'GNU Hello' <<<"$out" && grep -q '^jq-' <<<"$out" ||
  fail "new login shell doesn't have the Home Manager environment: $out"
pass "home bundle on a blank machine: installs Lix, activates packages, files, bash config and ~/.config; existing .bashrc and ~/.config file backed up as *.airgap.bak"

sh home.tar >/dev/null 2>&1 || fail "re-running the home bundle failed"
sudo /nix/var/nix/profiles/default/bin/nix-collect-garbage -d >/dev/null 2>&1
grep -q 'GNU Hello' <<<"$(bash -lic 'hello --version' 2>/dev/null)" || fail "home packages gone after GC"
pass "re-running is idempotent and the home generation survives nix-collect-garbage"
VMTEST

step "PASS"
"$VM" ssh 'sudo poweroff' 2>/dev/null || true
sleep 3
"$VM" stop
